mapper.update:
UPDATE knowledge_dataset SET status = #{status},
    activated_at = COALESCE(#{activatedAt}, activated_at)
WHERE version = #{version}

mapper.select:
SELECT 'FITS' AS type, standard_code, thinking_type AS target, reason, reviewed_by, reviewed_at
FROM knowledge_fits WHERE dataset_version = #{version}
UNION ALL
SELECT 'PREREQUISITE', standard_code, prerequisite_code, reason, reviewed_by, reviewed_at
FROM knowledge_prerequisite WHERE dataset_version = #{version}
UNION ALL
SELECT 'COVERS', standard_code, content_id, NULL, reviewed_by, reviewed_at
FROM knowledge_covers WHERE dataset_version = #{version}
ORDER BY 1, 2, 3

SELECT 'SEMESTER' AS kind, count(*) AS count FROM knowledge_standard_semester WHERE dataset_version = #{version}
UNION ALL SELECT 'FITS', count(*) FROM knowledge_fits WHERE dataset_version = #{version}
UNION ALL SELECT 'PREREQUISITE', count(*) FROM knowledge_prerequisite WHERE dataset_version = #{version}
UNION ALL SELECT 'COVERS', count(*) FROM knowledge_covers WHERE dataset_version = #{version}
